start_secure_session();require_once '../config/database.php';if(($_SESSION['role']??'')!=='dentist'){header('Location: ../auth/login.php');exit;}$uid=(int)$_SESSION['user_id'];$q=trim($_GET['q']??'');$sql="SELECT ro.*,CONCAT(u.first_name,' ',u.last_name) patient_name FROM restoration_orders ro JOIN users u ON u.id=ro.patient_id WHERE ro.dentist_id=?";$params=[$uid];$types='i';if($q!==''){$sql.=" AND (u.first_name LIKE ? OR u.last_name LIKE ? OR u.email LIKE ? OR ro.order_no LIKE ? OR ro.restoration_type LIKE ? OR ro.status LIKE ?)";$like='%'.$q.'%';$params=array_merge($params,array_fill(0,6,$like));$types.='ssssss';}$sql.=' ORDER BY ro.created_at DESC';$st=$conn->prepare($sql);$st->bind_param($types,...$params);$st->execute();$orders=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();require '../includes/ui.php';ui_header('Treatment Plans','dentist');ui_sidebar('dentist','treatment_plans.php');?>
<div class="page-head"><div><div class="eyebrow">TREATMENT PLANS</div><h1>Restoration Treatment Plans</h1><div class="muted">Create a removable or fixed restoration order, then review previous plans below.</div></div></div><section class="plan-chooser"><a class="plan-choice" href="restoration_form.php?type=removable"><div><h2>Removable Restoration</h2><p>Complete denture, partial denture, bite block, try-in, materials, shade, mould, instructions, and interactive tooth selection.</p></div><span>Create Plan</span></a><a class="plan-choice" href="restoration_form.php?type=fixed"><div><h2>Fixed Restoration</h2><p>Zircon, ceramic, PFM, alloy, buccal margin, staining, metal/pontic design, instructions, and interactive tooth selection.</p></div><span>Create Plan</span></a></section><section class="card"><div class="card-heading"><div><h2>Treatment Plan History</h2><p class="muted">Search by patient, order number, type, or status.</p></div></div><form class="directory-search" method="get"><input name="q" type="search" value="<?=e($q)?>" placeholder="Search treatment history"><button class="btn btn-primary">Search</button><?php if($q!==''):?><a class="btn btn-secondary" href="treatment_plans.php">Clear</a><?php endif;?></form><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Order No.</th><th>Patient</th><th>Restoration</th><th>Selected Teeth</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($orders as $o):$teeth=json_decode($o['selected_teeth']?:'[]',true);?><tr><td><?=e(date('M d, Y',strtotime($o['created_at'])))?></td><td><?=e($o['order_no']?:'—')?></td><td><?=e($o['patient_name'])?></td><td><?=e(ucfirst($o['restoration_type']))?></td><td><?=e(is_array($teeth)&&$teeth?implode(', ',$teeth):'—')?></td><td><span class="badge"><?=e($o['status'])?></span></td><td><a class="btn btn-secondary" href="restoration_view.php?id=<?=$o['id']?>">View</a><a class="btn btn-secondary" href="restoration_form.php?id=<?=$o['id']?>">Edit</a></td></tr><?php endforeach;if(!$orders):?><tr><td colspan="7" class="empty">No restoration treatment plans found.</td></tr><?php endif;?></tbody></table></div></section><?php ui_footer();?>
